      }

      override fun redact(`value`: RivalExtra): RivalExtra = value.copy(
        avatar_thumb = value.avatar_thumb?.let(ImageModel.ADAPTER::redact),
        authentication_info = value.authentication_info?.let(AuthenticationInfo.ADAPTER::redact),
        hashtag = value.hashtag?.let(Hashtag.ADAPTER::redact),
        top_host_info = value.top_host_info?.let(TopHostInfo.ADAPTER::redact),
        opt_pair_info = value.opt_pair_info?.let(OptPairInfo.ADAPTER::redact),
        game_tag = value.game_tag?.let(RivalsGameTag.ADAPTER::redact),
        gift_gallery_badge_info = value.gift_gallery_badge_info?.let(GiftGalleryBadgeInfo.ADAPTER::redact),
        activity_badge_info = value.activity_badge_info?.let(ActivityBadgeInfo.ADAPTER::redact),
        unknownFields = ByteString.EMPTY
      )
    }

    private const val serialVersionUID: Long = 0L
  }
